// ════════════════════════════════════════════════════════

export async function fetchProgress(
  env: LmsEnv,
  learnerId: string,
  stub?: Partial<ProgressEntry>[],
): Promise<{ progress: ProgressEntry[]; fromLms: boolean }> {
  try {
    const resp = await fetchLms(env, { path: `/api/v1/progress/user?userId=${learnerId}` });
    if (resp.ok) {
      const raw = (await resp.json()) as any;
      const data = raw.data || raw;
      const enrollments = data.enrollments || [];
      const lmsProgress = enrollments.map((e: any) => ({
        title: e.courseTitle || e.title || "",
        status: (e.status === "completed" ? "completed" : "in_progress") as "completed" | "in_progress",
        progress_pct: parseInt(e.progressPercent || e.progress_pct || "0") || 0,
      }));
      if (lmsProgress.length > 0) {
        return { progress: lmsProgress, fromLms: true };
      }
    }
    return { progress: (stub || []) as ProgressEntry[], fromLms: false };
  } catch {
    return { progress: (stub || []) as ProgressEntry[], fromLms: false };
  }
}

// ============================================================
// Shared LLM JSON Response Parser
// ============================================================
// LLMs often wrap JSON in markdown code blocks or return bare
// JSON. This extracts the JSON substring from a raw response,
// attempts JSON.parse, and returns the typed result or null.
// ============================================================

/**
 * Extract and parse JSON from an LLM response string.
 *
 * Handles:
 *  - Markdown code blocks: ` ```json\n{...}\n``` `
 *  - Bare JSON objects: `{...}`
 *  - Leading/trailing text around the JSON
 *  - Truncated/incomplete JSON (LLM stopped mid-generation)
 *
 * Returns the parsed object cast to T, or null if no valid JSON found.
 */
export function parseLlmJson<T>(response: string): T | null {
  // Try markdown code block first (most common LLM output pattern)
  const codeBlock = response.match(/```(?:json)?\s*\n?([\s\S]*?)\n?```/);
  const inner = codeBlock ? codeBlock[1] : response;

  // Try both patterns — use the longer match (prevents inner array from
  // outcompeting outer object when both are present)
  const strictArr = inner.match(/\[[\s\S]*\]/)?.[0];
  const strictObj = inner.match(/\{[\s\S]*\}/)?.[0];
  const strictJson = (strictArr && strictObj)
    ? (strictArr.length >= strictObj.length ? strictArr : strictObj)
    : (strictArr || strictObj);
  if (strictJson) {
    try {
      return JSON.parse(strictJson) as T;
    } catch { /* fall through to recovery */ }
  }

  // ── Recovery: LLM truncated JSON (missing closing braces/brackets) ──
  // Find the first `{` or `[`, then balance braces.
  const firstObj = inner.indexOf('{');
  const firstArr = inner.indexOf('[');
  let firstIdx = -1;
  if (firstObj === -1 && firstArr === -1) return null;
  if (firstObj === -1) firstIdx = firstArr;
  else if (firstArr === -1) firstIdx = firstObj;
  else firstIdx = Math.min(firstObj, firstArr);

  let candidate = inner.slice(firstIdx);
  const balanced = balanceBraces(candidate);
  if (!balanced) return null;
  candidate = balanced;

  try {
    return JSON.parse(candidate) as T;
  } catch {
    return null;
  }
}

/**
 * Add closing braces/brackets to balance an incomplete JSON string.
 * Returns the balanced string, or null if balancing fails.
 */
function balanceBraces(text: string): string | null {
  const stack: string[] = [];
  let inString = false;
  let escape = false;

  for (let i = 0; i < text.length; i++) {
    const ch = text[i];

    if (escape) {
      escape = false;
      continue;
    }

    if (ch === '\\' && inString) {
      escape = true;
      continue;
    }

    if (ch === '"') {
      inString = !inString;
      continue;
    }

    if (inString) continue;

    if (ch === '{' || ch === '[') {
      stack.push(ch === '{' ? '}' : ']');
    } else if (ch === '}' || ch === ']') {
      if (stack.length === 0) return null; // unexpected closing
      const expected = stack.pop()!;
      if (ch !== expected) return null; // mismatch
    }
  }

  // Add missing closing brackets in reverse order
  const closing = stack.reverse().join('');
  return text + closing;
}

// ============================================================
// Shared String Sanitizer
// ============================================================
// Strips quotes, trims whitespace, and caps length. Used by
// multiple workers to clean LLM-generated string fields before
// including them in API responses.
// ============================================================

/**
 * Sanitize an LLM-generated string.
 *
 * - Strips leading/trailing quotes (common LLM artifact)
 * - Trims whitespace
 * - Caps at maxLength (default 500 chars)
 * - Returns empty string for null/undefined input
 *
 * @param text       Raw string from LLM output (may be undefined)
 * @param maxLength  Maximum allowed length (default 500)
 */
export function sanitize(text: string | undefined, maxLength: number = 500): string {
  if (!text) return '';
  return text.replace(/^["']+|["']+$/g, '').trim().slice(0, maxLength);
}

